import Foundation
import Observation

/// Authors the rc files launchd runs.
///
/// The generated files still read `settings.env` and the theme's env at run
/// time rather than baking values in. That keeps borders correct at login even
/// if the app never starts — the GUI must never be in the boot path — while
/// still making the app the single author of the file itself.
@MainActor
@Observable
final class RCGenerator {
    private(set) var lastOutcomes: [String: GeneratedFile.Outcome] = [:]

    private let log: CommandLog
    init(log: CommandLog) { self.log = log }

    static var bordersrc: GeneratedFile {
        GeneratedFile(url: Paths.home.appending(path: ".config/borders/bordersrc"))
    }

    static var yabairc: GeneratedFile {
        GeneratedFile(url: Paths.home.appending(path: ".config/yabai/yabairc"))
    }

    var driftedFiles: [String] {
        [Self.bordersrc, Self.yabairc]
            .filter(\.hasDrifted)
            .map { $0.url.lastPathComponent }
    }

    private static let header = """
    #!/bin/bash
    # Generated by Macarchy Settings — edits here are reported, not silently kept.
    #
    # Values still resolve at run time from settings.env and the active theme, so
    # this works at login whether or not the app is running. Regions marked
    # "macarchy:keep" are preserved across regeneration.

    """

    // MARK: - bordersrc

    func generateBordersRC() {
        let file = Self.bordersrc
        let kept = file.preservedRegions()
        let extra = kept["extra"].map { "\n\(GeneratedFile.beginKeep) extra\n\($0)\n\(GeneratedFile.endKeep)\n" } ?? """

        \(GeneratedFile.beginKeep) extra
        \(GeneratedFile.endKeep)

        """

        let content = Self.header + """
        set -euo pipefail

        BORDERS_BIN="/opt/homebrew/opt/borders/bin/borders"
        # Local renderer keeps square borders rectangular on translucent windows.
        if [ -x "$HOME/.local/bin/macarchy-borders" ]; then
          BORDERS_BIN="$HOME/.local/bin/macarchy-borders"
        fi

        THEMES_DIR="$HOME/.config/macarchy-settings/themes"
        CURRENT_THEME="$(cat "$THEMES_DIR/.current" 2>/dev/null || true)"
        if [ -n "$CURRENT_THEME" ] && [ -f "$THEMES_DIR/$CURRENT_THEME/theme.env" ]; then
          # shellcheck source=/dev/null
          source "$THEMES_DIR/$CURRENT_THEME/theme.env"
        fi

        SETTINGS_ENV="$HOME/.config/macarchy-settings/settings.env"
        if [ -f "$SETTINGS_ENV" ]; then
          # shellcheck source=/dev/null
          source "$SETTINGS_ENV"
        fi

        # Theme owns colour; settings owns geometry. Defaults only apply if neither set it.
        BORDER_STYLE="${BORDER_STYLE:-square}"
        BORDER_ACTIVE="${BORDER_ACTIVE:-0xff45e8ff}"
        BORDER_INACTIVE="${BORDER_INACTIVE:-0x00000000}"
        BORDER_WIDTH="${BORDER_WIDTH:-6.0}"
        BORDERS_VISIBLE="${BORDERS_VISIBLE:-true}"
        BORDERS_BLACKLIST="${BORDERS_BLACKLIST:-}"

        case ",$BORDERS_BLACKLIST," in
          *",iPhone Mirroring,"*) ;;
          ",,") BORDERS_BLACKLIST="iPhone Mirroring" ;;
          *) BORDERS_BLACKLIST="$BORDERS_BLACKLIST,iPhone Mirroring" ;;
        esac

        if [ "$BORDERS_VISIBLE" != "true" ]; then
          BORDER_ACTIVE="0x00000000"
          BORDER_INACTIVE="0x00000000"
          BORDER_WIDTH="0.0"
          BORDER_ANIMATION_COLORS=""
        fi

        if [ -n "${BORDER_ANIMATION_COLORS:-}" ]; then
          read -r -a BORDER_COLORS <<< "$BORDER_ANIMATION_COLORS"
          FIRST="${BORDER_COLORS[0]}"
          SECOND="${BORDER_COLORS[3]:-${BORDER_COLORS[1]:-$FIRST}}"
          if [ "${BORDER_ANIMATION_EFFECT:-glow}" = "glow" ]; then
            ACTIVE_ARG="active_color=glow($FIRST)"
          else
            ACTIVE_ARG="active_color=gradient(top_left=$FIRST,bottom_right=$SECOND)"
          fi
        else
          ACTIVE_ARG="active_color=$BORDER_ACTIVE"
        fi
        \(extra)
        exec "$BORDERS_BIN" \\
          style="$BORDER_STYLE" \\
          width="$BORDER_WIDTH" \\
          hidpi=on \\
          background_color=0x00000000 \\
          "$ACTIVE_ARG" \\
          inactive_color="$BORDER_INACTIVE" \\
          blacklist="$BORDERS_BLACKLIST"

        """

        record("bordersrc", file.write(content, reason: "borders settings changed"))
    }

    // MARK: - yabairc

    /// yabai config keys the app owns, with the settings.env variable each
    /// resolves from and the fallback if nothing has been set.
    static func envName(forYabaiKey key: String) -> String? {
        yabaiKeys.first { $0.key == key }?.env
    }

    static let yabaiKeys: [(key: String, env: String, fallback: String)] = [
        ("layout", "YABAI_LAYOUT", "bsp"),
        ("window_insertion_point", "YABAI_INSERTION_POINT", "last"),
        ("window_placement", "YABAI_WINDOW_PLACEMENT", "second_child"),
        ("split_type", "YABAI_SPLIT_TYPE", "auto"),
        ("auto_balance", "YABAI_AUTO_BALANCE", "off"),
        ("insert_feedback_color", "YABAI_INSERT_FEEDBACK_COLOR", "0x01000000"),
        ("top_padding", "YABAI_TOP_PADDING", "8"),
        ("bottom_padding", "YABAI_BOTTOM_PADDING", "8"),
        ("left_padding", "YABAI_LEFT_PADDING", "8"),
        ("right_padding", "YABAI_RIGHT_PADDING", "8"),
        ("window_gap", "YABAI_WINDOW_GAP", "8"),
        ("mouse_follows_focus", "YABAI_MOUSE_FOLLOWS_FOCUS", "off"),
        ("mouse_modifier", "YABAI_MOUSE_MODIFIER", "ctrl"),
        ("mouse_action1", "YABAI_MOUSE_ACTION1", "move"),
        ("mouse_action2", "YABAI_MOUSE_ACTION2", "resize"),
        ("mouse_drop_action", "YABAI_MOUSE_DROP_ACTION", "stack")
    ]

    /// Splits an existing hand-written yabairc into the parts the app owns
    /// (config assignments) and the parts it must not touch — the scripting
    /// addition, signal handlers and helper invocations, none of which are data.
    static func seedRegions(from text: String) -> (signals: String, rules: String) {
        var signals: [String] = []
        var rules: [String] = []

        for raw in text.split(separator: "\n", omittingEmptySubsequences: false) {
            let line = String(raw)
            let trimmed = line.trimmingCharacters(in: .whitespaces)
            if trimmed.hasPrefix("#!") { continue }
            if trimmed.contains("yabai -m config ") { continue }
            if trimmed.contains("yabai -m rule ") { rules.append(line); continue }
            // Section comments that belong to config blocks go with them.
            let configHeadings = ["# BSP layout", "# Padding and gaps", "# Mouse controls",
                                  "# Float system apps"]
            if configHeadings.contains(where: { trimmed.hasPrefix($0) }) { continue }
            signals.append(line)
        }

        func tidy(_ lines: [String]) -> String {
            var out = lines
            while out.first?.trimmingCharacters(in: .whitespaces).isEmpty == true { out.removeFirst() }
            while out.last?.trimmingCharacters(in: .whitespaces).isEmpty == true { out.removeLast() }
            return out.joined(separator: "\n")
        }
        return (tidy(signals), tidy(rules))
    }

    func generateYabaiRC() {
        let file = Self.yabairc
        var kept = file.preservedRegions()

        // First run: carve the hand-written file into keep regions so nothing
        // that isn't configuration is lost.
        if kept["signals"] == nil || kept["rules"] == nil,
           let existing = try? String(contentsOf: file.url, encoding: .utf8) {
            let seeded = Self.seedRegions(from: existing)
            if kept["signals"] == nil { kept["signals"] = seeded.signals }
            if kept["rules"] == nil { kept["rules"] = seeded.rules }
        }

        let config = Self.yabaiKeys
            .map { "yabai -m config \($0.key) \"${\($0.env):-\($0.fallback)}\"" }
            .joined(separator: "\n")

        func keepBlock(_ name: String) -> String {
            "\(GeneratedFile.beginKeep) \(name)\n\(kept[name] ?? "")\n\(GeneratedFile.endKeep)"
        }

        let content = """
        #!/usr/bin/env bash
        # Generated by Macarchy Settings — edits here are reported, not silently kept.
        #
        # Config values resolve from settings.env at run time, so this is correct at
        # login whether or not the app is running. Everything inside macarchy:keep
        # is yours and survives regeneration — the scripting addition, signal
        # handlers and rules are not configuration and are never rewritten.

        SETTINGS_ENV="$HOME/.config/macarchy-settings/settings.env"
        if [ -f "$SETTINGS_ENV" ]; then
          # shellcheck source=/dev/null
          source "$SETTINGS_ENV"
        fi

        \(keepBlock("signals"))

        # Layout, padding and mouse — owned by the Layout pane.
        \(config)

        \(keepBlock("rules"))

        """

        record("yabairc", file.write(content, reason: "layout settings changed"))
    }

    private func record(_ name: String, _ outcome: GeneratedFile.Outcome) {
        lastOutcomes[name] = outcome
        switch outcome {
        case .unchanged:
            break
        case .written:
            log.note("generated \(name)", "")
        case .writtenOverDrift(let snapshot):
            log.note("generated \(name)", "hand edits found — snapshotted as \(snapshot ?? "?")")
        case .failed(let message):
            log.note("generating \(name) failed", message)
        }
    }
}
